def components(I, val, conn=4):
    H,W=I.shape
    cells={(r,c) for r in range(H) for c in range(W) if I[r,c]==val}
    offs=[(d1,d2) for d1 in(-1,0,1) for d2 in(-1,0,1) if (d1,d2)!=(0,0) and (conn==8 or abs(d1)+abs(d2)==1)]
    seen=set(); cs=[]
    for cell in sorted(cells):
        if cell in seen: continue
        stack=[cell]; c=set()
        while stack:
            x=stack.pop()
            if x in seen or x not in cells: continue
            seen.add(x); c.add(x)
            r,cc=x
            for dr,dc in offs:
                nr,nc=r+dr,cc+dc
                if (nr,nc) in cells and (nr,nc) not in seen:
                    stack.append((nr,nc))
        cs.append(c)
    return cs

